import {PICO_BOARDS} from './pico-boards.js';
import {crc32} from './project-zip.js';
export function packPicoImage(bytes,id){const out=new Uint8Array(80+bytes.length),v=new DataView(out.buffer);out.set(new TextEncoder().encode('CFPICO1\0'));out.set(new TextEncoder().encode(id),8);v.setUint32(64,bytes.length,true);v.setUint32(68,crc32(bytes),true);out.set(bytes,80);validatePicoImage(out,id);return out;}
export function validatePicoImage(image,id){const b=PICO_BOARDS[id];if(!b||!(image instanceof Uint8Array)||image.length<88)throw Error('Pico firmware başlığı geçersiz.');const v=new DataView(image.buffer,image.byteOffset,image.byteLength),dec=new TextDecoder(),bytes=image.subarray(80);if(dec.decode(image.subarray(0,8))!=='CFPICO1\0'||dec.decode(image.subarray(8,64)).replace(/\0.*$/s,'')!==id||image.subarray(72,80).some(x=>x)||v.getUint32(64,true)!==bytes.length||bytes.length>b.flashSize||v.getUint32(68,true)!==crc32(bytes))throw Error('Pico firmware hedefi/boyutu/checksum geçersiz.');const sp=v.getUint32(80,true),pc=v.getUint32(84,true);if(sp!==0x20000000+b.ram||!(pc&1)||pc<0x10000008||pc>=0x10000000+bytes.length)throw Error('Pico reset vektörü geçersiz.');return bytes;}
